from importlib.metadata import distributions

def snapshot(items):
    rows = []
    for dist in items:
        name = dist.metadata.get('Name')
        version = dist.version
        if name and version:
            rows.append((name, version))
    return sorted(rows, key=lambda row: row[0].casefold())

rows = snapshot(distributions())
assert all(name and version for name, version in rows)
assert rows == sorted(rows, key=lambda row: row[0].casefold())
print('distribution snapshot checked')
